<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Controllers\Controller;use App\Models\User;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;class AuthController extends Controller{public function register(Request $r){$d=$r->validate(['name'=>'required|string|max:120','email'=>'required|email|max:190|unique:users','password'=>'required|string|min:8|confirmed']);$u=User::create([...$d,'role'=>'client','is_active'=>true]);return response()->json(['data'=>['user'=>$u,'token'=>$u->createToken('web')->plainTextToken]],201);}public function login(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required|string']);$u=User::where('email',$d['email'])->first();if(!$u||!Hash::check($d['password'],$u->password)||!$u->is_active)return response()->json(['message'=>'Identifiants invalides ou compte désactivé.'],422);return ['data'=>['user'=>$u,'token'=>$u->createToken('web')->plainTextToken]];}public function logout(Request $r){$r->user()->currentAccessToken()->delete();return response()->noContent();}public function me(Request $r){return ['data'=>$r->user()];}}
